  f.complete();assertThrows(RuntimeException.class,()->f.prepared.tx(()->service.finish(f.ref)));service=provider(f.f.writes,Clock.fixed(f.f.clock.instant().minusSeconds(1),ZoneOffset.UTC));assertThrows(RuntimeException.class,()->service.finish(f.ref));assertEquals(0,receipts());service=provider(f.f.writes,f.f.clock);assertThrows(RuntimeException.class,()->service.finish(new FrozenSourceStagePlan.Reference(f.ref.ownerId(),"b".repeat(64),f.ref.indexHash())));assertEquals(0,receipts());var proofs=org.mockito.Mockito.mock(CatalogSourceFinalProofService.class);var archives=org.mockito.Mockito.mock(CatalogSourceFinalArchiveService.class);var plans=org.mockito.Mockito.mock(FrozenSourceStagePlanService.class);var universes=org.mockito.Mockito.mock(FrozenSourceUniverseService.class);var receipts=org.mockito.Mockito.mock(CatalogSourceFinalReceiptService.class);var summaries=org.mockito.Mockito.mock(SourceRunAnalysisService.class);var writes=org.mockito.Mockito.mock(SharedWriteExecutor.class);var permits=org.mockito.Mockito.mock(CatalogSourceFinalCommitPermitService.class);var manager=new DataSourceTransactionManager(f.f.source);for(String category:List.of("agent","skill","workflow","model"))assertNotNull(new CatalogSourceFinalizationService(proofs,archives,plans,universes,receipts,summaries,writes,permits,manager,f.f.clock,category));for(String category:List.of("","AGENT","news_tech"))assertThrows(RuntimeException.class,()->new CatalogSourceFinalizationService(proofs,archives,plans,universes,receipts,summaries,writes,permits,manager,f.f.clock,category));org.mockito.Mockito.verifyNoInteractions(proofs,archives,plans,universes,receipts,summaries,writes,permits);
